#!/bin/bash
# Copies the live desktop configs into this repo. Run it, look at `git diff`,
# then commit and push. Reads only; never changes the live system.
set -euo pipefail
repo=$(dirname "$(readlink -f "$0")")
cfg=$HOME/.config

echo "== ~/.config -> config/"
mkdir -p "$repo/config"
rsync -a --delete \
  --exclude='*.bak*' --exclude='bookmarks' \
  --exclude='wallpaper-current' --exclude='hyprpaper.conf' \
  --exclude='hyprland.lua.autogenerated' \
  "$cfg"/{hypr,waybar,kitty,mako,fuzzel,rofi,btop,gtk-3.0,gtk-4.0,qt6ct} \
  "$cfg/starship.toml" "$repo/config/"

echo "== tuigreet patch (~/git/tuigreet vs 0.11.1) -> ~/hypr-setup"
tg=$HOME/git/tuigreet
if [[ -d $tg ]]; then
  git -C "$tg" add -N --ignore-errors crates >/dev/null 2>&1 || true
  git -C "$tg" diff 0.11.1 -- crates >"$HOME/hypr-setup/tuigreet-night-sky.patch"
fi

echo "== ~/hypr-setup -> setup/"
rsync -a --delete --exclude='cleanup-and-theme.sh' "$HOME/hypr-setup/" "$repo/setup/"

echo "== boot: Limine theme, kernel options, initramfs, Plymouth, console, greetd"
b=$repo/boot
mkdir -p "$b/limine" "$b/plymouth" "$b/etc"
sed -n '/^### Theme/,/^terse:/p' /boot/limine.conf >"$b/limine/limine-theme.conf"
sed -n '/^# Boot rice/,/^KERNEL_CMDLINE/p' /etc/default/limine >"$b/limine/default-limine.snippet"
rsync -a --delete --exclude='background.png' /usr/share/plymouth/themes/aurora/ "$b/plymouth/aurora/"
cp /etc/plymouth/plymouthd.conf "$b/plymouth/"
cp /etc/mkinitcpio.conf.d/00-hooks.conf "$b/etc/mkinitcpio-00-hooks.conf"
grep -v '^#' /etc/vconsole.conf | grep . >"$b/etc/vconsole.conf"
cp /etc/systemd/system/greetd.service.d/10-plymouth.conf "$b/etc/greetd-10-plymouth.conf"

echo "done; now: git -C '$repo' status"
